window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["quantization"]={"title":"量化：把连续参数压到有限格点","subtitle":"从 scale、zero-point 和舍入误差，到粒度、异常值、PTQ/QAT、权重/激活/KV 与硬件内核。","thesis":"量化把浮点数映射到有限整数格点，以近似误差换取存储、带宽和计算收益。位宽只是标签；真实结果由<b>范围选择、量化粒度、异常值、校准数据、计算精度和硬件内核</b>共同决定。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"对称 INT3 范围 −4…3","rule":"s=1.2/3=0.4","steps":"x=−1.1→q=−3→−1.2","interpretation":"舍入造成小误差，超出范围的 1.25 被截断"}}],"formulas":[{"id":"quantization-linear-map","section":2,"formulaIndex":1,"symbols":[{"name":"x","meaning":"执行量化前的原始浮点数值","evidence":"x 是原浮点值"},{"name":"s","meaning":"相邻整数格点对应的浮点步长尺度","evidence":"s 是相邻整数格点代表的浮点步长"},{"name":"round","meaning":"把实数舍入为最近整数的操作","evidence":"round 取最近整数"},{"name":"z","meaning":"让某个整数编码精确对应浮点零的零点","evidence":"z 是让某个整数格点对应浮点零的 zero-point"},{"name":"clip","meaning":"把超出范围的结果限制到整数上下限","evidence":"clip 把超范围结果限制在整数下限"},{"name":"q","meaning":"量化后存储和计算使用的整数编码","evidence":"最终编码是 q"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"量化把连续浮点数映射到有限离散编码，并在计算时使用近似值。","evidence":"映射到有限个离散格点"},"problem":{"answer":"它以可控数值误差减少模型权重、激活或 KV 的存储与带宽需求。","evidence":"更低位宽减少模型读取的字节"},"inputOutput":{"answer":"输入是浮点权重、激活或缓存，输出是整数编码、尺度和还原近似值。","evidence":"输出是整数编码、尺度元数据和计算时还原的近似值"},"mechanism":{"answer":"区间内数值舍入到格点，区间外截断，导致原值差异部分消失。","evidence":"落在同一格的连续值会变得不可区分"},"interpretation":{"answer":"文件变小说明数值表示更紧凑，不表示推理仍使用原始精确数值。","evidence":"量化不是压缩文件后无损解压"},"boundary":{"answer":"位宽标签不含对象、符号范围和量化配置，不能由 INT4 单独推断效果。","evidence":"不能只看“INT4”猜范围"}},{"section":2,"definition":{"answer":"线性量化用 scale 和 zero-point 在浮点区间与整数格点间建立映射。","evidence":"浮点范围怎样对应整数范围"},"problem":{"answer":"它明确编码、舍入、截断和反量化怎样产生可计算的近似值。","evidence":"它通常不再与 x 完全相等"},"inputOutput":{"answer":"输入是浮点 x、尺度、零点和整数范围，输出是编码 q 与近似值 x̂。","evidence":"最终编码是 q"},"mechanism":{"answer":"先除尺度并舍入、加零点、截断到上下限，再按尺度和零点反量化。","evidence":"把超范围结果限制在整数下限"},"interpretation":{"answer":"误差由位宽、范围和步长共同决定，对称与非对称还会改变格点利用。","evidence":"范围与步长共同选择的结果"},"boundary":{"answer":"覆盖极值会让主体格点变粗，截断极值则可能让重要异常值饱和。","evidence":"覆盖全部极值"}},{"section":3,"definition":{"answer":"数值例把四个浮点值映射到对称 INT3 格点，再计算反量化绝对误差。","evidence":"四个数怎样落到 INT3 格点"},"problem":{"answer":"它展示舍入误差与超范围截断，并说明改变 scale 的误差权衡。","evidence":"量化后误差多大"},"inputOutput":{"answer":"输入是 INT3 范围、最大绝对值和四个原值，输出编码、近似值与误差。","evidence":"对称 INT3 范围 −4…3"},"mechanism":{"answer":"以零点四为步长除、舍入并截断，再乘零点四还原近似值。","evidence":"s=1.2/3=0.4"},"interpretation":{"answer":"普通值产生小舍入误差，一点二五因超过正上限而被截到一点二。","evidence":"超出范围的 1.25 被截断"},"boundary":{"answer":"扩大 scale 覆盖一点二五会使其他格点更粗，因此不存在对所有值都更优的范围。","evidence":"其他格点更粗"}},{"section":4,"definition":{"answer":"量化粒度规定一整个张量、每通道或每个权重组共享一个尺度。","evidence":"per-tensor 为整张张量共用一个尺度"},"problem":{"answer":"它减少少数异常通道支配整张矩阵范围而压粗多数普通值的问题。","evidence":"为什么整张矩阵一个 scale 常被少数异常通道支配"},"inputOutput":{"answer":"输入是权重、分组轴和组大小，输出是各组整数编码与尺度元数据。","evidence":"输出是各组整数编码与尺度元数据"},"mechanism":{"answer":"更细分组分别适配局部范围，以更多 scale、索引和内核复杂度换较小误差。","evidence":"细粒度让每组适配自己的范围"},"interpretation":{"answer":"同为四位的文件若分组轴、大小和打包格式不同，不能直接比较。","evidence":"模型文件“4-bit”不可直接横比"},"boundary":{"answer":"更细粒度不保证更快，不支持布局时元数据和反量化会抵消收益。","evidence":"元数据读取和反量化可能抵消收益"}},{"section":5,"definition":{"answer":"异常值是幅度远大于主体的少数权重或激活，会拉大量化范围与步长。","evidence":"统一 scale 为覆盖极值而变大"},"problem":{"answer":"它解释少量大激活为何让多数普通值挤入靠近零的少数格点。","evidence":"少量大激活为什么让大多数普通值挤在零附近"},"inputOutput":{"answer":"输入是待量化层与校准激活，输出是范围、高精通道或补偿后的权重。","evidence":"输出是范围、保留高精度通道或经过补偿的权重"},"mechanism":{"answer":"不同方法保留异常通道、迁移尺度或按曲率与激活重要性补偿权重。","evidence":"它们分别处理异常通道、权重激活平衡和权重重要性"},"interpretation":{"answer":"平均误差小仍可能令少数关键 logits 排序翻转并改变工具或拒答动作。","evidence":"平均误差小不代表行为安全"},"boundary":{"answer":"盲目剪裁会伤害稀有 token、语言或长上下文，校准集必须覆盖真实难例。","evidence":"不能只用短英文百科"}},{"section":6,"definition":{"answer":"PTQ 在训练后量化，QAT 训练中模拟误差，QLoRA 在量化基座上训练适配器。","evidence":"三者的输出分别是量化模型、适应量化误差的新模型和可挂载适配器"},"problem":{"answer":"它帮助按误差敏感度和成本决定仅校准、重新训练还是参数高效适配。","evidence":"什么时候只用校准数据，什么时候需要重新训练"},"inputOutput":{"answer":"输入是原模型、校准或训练数据，输出依次为量化模型、新模型或适配器。","evidence":"保持低位基座冻结，只训练高精度低秩适配器"},"mechanism":{"answer":"PTQ 估尺度，QAT 在前向模拟舍入让权重适应，QLoRA 只更新低秩分支。","evidence":"在训练前向中模拟舍入与截断"},"interpretation":{"answer":"先以低成本 PTQ 为基线，仅在关键切片不达标时承担更高训练成本。","evidence":"应先从低成本 PTQ 基线开始"},"boundary":{"answer":"PTQ 仍需代表性数据，QAT 会过拟合，QLoRA 的最终合并产物还需重测。","evidence":"最终部署是否合并和重新量化要另做评测"}},{"section":7,"definition":{"answer":"量化速度收益取决于硬件内核、打包、负载与当前瓶颈，而非仅文件大小。","evidence":"省显存不保证更快"},"problem":{"answer":"它解释 INT4 文件缩小到 FP16 四分之一时端到端吞吐为何可能不升。","evidence":"为什么端到端吞吐可能不升"},"inputOutput":{"answer":"输入是目标硬件、负载和量化产物，输出是延迟、吞吐、显存、功耗等实测。","evidence":"输出应包括首 token 延迟、每 token 延迟、吞吐"},"mechanism":{"answer":"低位内核减少权重读取，反量化、格式转换、启动和小 batch 又会增加开销。","evidence":"会抵消带宽收益"},"interpretation":{"answer":"decode 常带宽受限更可能获益，prefill 是否获益取决于低精计算支持。","evidence":"prefill 是一次处理整段输入提示"},"boundary":{"answer":"能装入显存只通过容量门，CPU offload 的 PCIe 搬运仍可能违反延迟 SLO。","evidence":"不等于延迟满足 SLO"}},{"section":8,"definition":{"answer":"量化与推测解码、LoRA 合并、KV 压缩和张量并行会产生交互误差。","evidence":"量化误差会与后续优化叠加"},"problem":{"answer":"它防止把各单项优化的测试结果直接相加并当作最终产物质量。","evidence":"能把单项测试相加吗"},"inputOutput":{"answer":"输入是完整优化配方与最终模型，输出是重新量化校准后的端到端指标。","evidence":"按真实最终产物重新量化或校准"},"mechanism":{"answer":"合并改变权重范围、KV 误差耦合注意力、布局改变通信，因此旧 scale 会失效。","evidence":"LoRA 合并后权重范围变化"},"interpretation":{"answer":"同为 INT4 若基座、对象、粒度、数据、内核或硬件不同，就不可复现比较。","evidence":"否则“同为 INT4”无法复现"},"boundary":{"answer":"不能用更多重试掩盖压缩损失，因为会增加成本、延迟和选择偏差。","evidence":"不可把压缩损失用更多重试隐藏"}},{"section":9,"definition":{"answer":"量化评测同时检查逐样本排序翻转、长尾质量与目标硬件系统收益。","evidence":"评测要抓排序翻转和长尾退化"},"problem":{"answer":"它解释平均困惑度几乎不变时，工具和安全动作仍可能明显退化。","evidence":"为什么工具调用和安全仍可能明显变差"},"inputOutput":{"answer":"输入是相同负载下量化前后模型，输出质量差、延迟、吞吐、资源和失败样例。","evidence":"输出量化前后质量差、延迟区间"},"mechanism":{"answer":"按能力与风险切片比较 logits 排序，再在真实硬件测各延迟分位和成功成本。","evidence":"按通用能力、目标任务、稀有 token"},"interpretation":{"answer":"平均困惑度小变化不能排除接近边界的关键 token 排序翻转。","evidence":"不能排除少数关键动作排序翻转"},"boundary":{"answer":"只有硬风险切片不退化且系统收益在目标硬件成立，配置才能发布。","evidence":"量化配置才是可行方案"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>手算线性量化与误差；区分对称/非对称和量化粒度；理解 PTQ/QAT 与异常值处理；联合评测质量、显存和延迟。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>有限位宽为什么会丢信息<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">把任意浮点数塞进 16 个 INT4 格点，哪些差异必然消失？</p><p><b>量化</b>把原本可取很多连续小数的数值，映射到有限个离散格点。INT4 表示每个编码使用 4 bit，因此只有 2⁴=16 种编码；具体是 −8…7、−7…7 还是别的范围，还取决于有符号约定与保留值，不能只看“INT4”猜范围。</p><p>一个区间内落在同一格的连续值会变得不可区分，区间外的值被截断；更低位宽减少模型读取的字节，却增大舍入或饱和误差。输入是浮点权重、激活或 KV 缓存，输出是整数编码、尺度元数据和计算时还原的近似值。</p><p>量化不是压缩文件后无损解压。推理使用近似权重或激活，误差会沿网络传播；神经网络冗余和合适尺度让许多任务能够容忍，但关键决策边界仍可能翻转。</p><div class=\"dd-note\"><b>先问对象：</b>权重量化省模型带宽；激活量化影响中间算子；KV 量化影响长上下文容量。三者不能用“INT4”一词概括。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>线性量化的 scale 与 zero-point<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">浮点范围怎样对应整数范围？</p><div class=\"dd-formula\" data-formula-id=\"quantization-linear-map\" data-display=\"mathml\"><math display=\"block\" aria-label=\"整数编码 q 等于浮点值 x 除以尺度 s 后舍入，加零点 z，再截断到整数上下限；反量化值 x hat 等于 s 乘 q 减 z\"><mtable><mtr><mtd><mi>q</mi><mo>=</mo><mi>clip</mi><mo>(</mo><mi>round</mi><mo>(</mo><mfrac><mi>x</mi><mi>s</mi></mfrac><mo>)</mo><mo>+</mo><mi>z</mi><mo>,</mo><msub><mi>q</mi><mtext>最小</mtext></msub><mo>,</mo><msub><mi>q</mi><mtext>最大</mtext></msub><mo>)</mo></mtd></mtr><mtr><mtd><mover><mi>x</mi><mo>^</mo></mover><mo>=</mo><mi>s</mi><mo>(</mo><mi>q</mi><mo>−</mo><mi>z</mi><mo>)</mo></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>x</code> 是原浮点值，<code>s</code> 是相邻整数格点代表的浮点步长，<code>round</code> 取最近整数，<code>z</code> 是让某个整数格点对应浮点零的 zero-point。<code>clip</code> 把超范围结果限制在整数下限 <code>q最小</code> 与上限 <code>q最大</code>；最终编码是 <code>q</code>，反量化近似值是 <code>x̂</code>，它通常不再与 x 完全相等。</p><p>非对称量化可用完整范围覆盖偏移分布；对称量化通常 z=0、范围围绕零，内核更简单但可能浪费一侧格点。输出误差应解释为范围与步长共同选择的结果，而非仅由位宽决定。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>选择</th><th>优势</th><th>代价</th></tr></thead><tbody><tr><td>对称</td><td>零点简单、乘加高效</td><td>偏移分布浪费范围</td></tr><tr><td>非对称</td><td>贴合任意 min/max</td><td>零点修正更复杂</td></tr><tr><td>截断极值</td><td>主体格点更细</td><td>异常值饱和</td></tr><tr><td>覆盖全部极值</td><td>不截断</td><td>主体量化粗糙</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>运行示例：四个数怎样落到 INT3 格点<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">对称 INT3 范围 −4…3，浮点最大绝对值 1.2，量化后误差多大？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 250\" role=\"img\" aria-label=\"四个浮点权重映射到对称 INT3 格点并反量化\"><line x1=\"60\" y1=\"125\" x2=\"650\" y2=\"125\" stroke=\"#6b7484\" stroke-width=\"2\"/><g fill=\"#6b8cbe\" class=\"svg-t\" font-size=\"10\"><circle cx=\"80\" cy=\"125\" r=\"5\"/><text x=\"80\" y=\"150\" text-anchor=\"middle\">−1.6</text><circle cx=\"160\" cy=\"125\" r=\"5\"/><text x=\"160\" y=\"150\" text-anchor=\"middle\">−1.2</text><circle cx=\"240\" cy=\"125\" r=\"5\"/><text x=\"240\" y=\"150\" text-anchor=\"middle\">−0.8</text><circle cx=\"320\" cy=\"125\" r=\"5\"/><text x=\"320\" y=\"150\" text-anchor=\"middle\">−0.4</text><circle cx=\"400\" cy=\"125\" r=\"5\"/><text x=\"400\" y=\"150\" text-anchor=\"middle\">0</text><circle cx=\"480\" cy=\"125\" r=\"5\"/><text x=\"480\" y=\"150\" text-anchor=\"middle\">0.4</text><circle cx=\"560\" cy=\"125\" r=\"5\"/><text x=\"560\" y=\"150\" text-anchor=\"middle\">0.8</text><circle cx=\"640\" cy=\"125\" r=\"5\"/><text x=\"640\" y=\"150\" text-anchor=\"middle\">1.2</text></g><circle cx=\"180\" cy=\"90\" r=\"7\" fill=\"#d3a05a\"/><text x=\"180\" y=\"75\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">x=−1.1→q=−3→−1.2</text><path d=\"M180,96 L160,119\" stroke=\"#d3a05a\"/><circle cx=\"310\" cy=\"62\" r=\"7\" fill=\"#4f9d78\"/><text x=\"310\" y=\"47\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">x=−.35→q=−1→−.4</text><path d=\"M310,68 L320,119\" stroke=\"#4f9d78\"/><circle cx=\"462\" cy=\"90\" r=\"7\" fill=\"#4f9d78\"/><text x=\"462\" y=\"75\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">x=.31→q=1→.4</text><path d=\"M462,96 L480,119\" stroke=\"#4f9d78\"/><circle cx=\"665\" cy=\"62\" r=\"7\" fill=\"#c77b72\"/><text x=\"595\" y=\"47\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">x=1.25→clip q=3→1.2</text><path d=\"M665,68 L640,119\" stroke=\"#c77b72\"/></svg><figcaption>图 1　s=1.2/3=0.4；舍入造成小误差，超出范围的 1.25 被截断。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>x</th><th>round(x/.4)</th><th>q</th><th>x̂=.4q</th><th>|误差|</th></tr></thead><tbody><tr><td>−1.10</td><td>−3</td><td>−3</td><td>−1.20</td><td>.10</td></tr><tr><td>−.35</td><td>−1</td><td>−1</td><td>−.40</td><td>.05</td></tr><tr><td>.31</td><td>1</td><td>1</td><td>.40</td><td>.09</td></tr><tr><td>1.25</td><td>3</td><td>3</td><td>1.20</td><td>.05（截断）</td></tr></tbody></table></div><p>若为覆盖 1.25 把 s 调到 .4167，其他格点更粗。真实校准就是在主体误差与极值截断之间选择。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>粒度越细，误差低但元数据与内核更复杂<span class=\"dd-badge eng\">粒度</span></h2><p class=\"dd-lead\">为什么整张矩阵一个 scale 常被少数异常通道支配？</p><p><code>per-tensor</code> 为整张张量共用一个尺度，<code>per-channel</code> 为每个输出通道单独设尺度，<code>group-wise</code> 则把若干连续权重分为一组。细粒度让每组适配自己的范围，通常减少误差，代价是更多 scale、索引和专用内核开销。</p><div class=\"dd-note math\"><b>元数据账：</b>4096×4096 权重使用 per-tensor 时只有 1 个 scale；per-channel 有 4096 个；若每 128 个权重一组，约有 131072 个 scale。</div><p>输入是权重矩阵、分组轴和组大小，输出是各组整数编码与尺度元数据。scale 元数据相对权重通常仍小，但反量化和布局决定速度。不同库的 group size、轴和打包格式不同，模型文件“4-bit”不可直接横比。</p><p>粒度更细而误差更低，不代表目标硬件更快；若内核不支持该布局，元数据读取和反量化可能抵消收益。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>异常值决定范围，也可能决定能力<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">少量大激活为什么让大多数普通值挤在零附近？</p><p>统一 scale 为覆盖极值而变大，主体值会挤入少数格点。LLM.int8 把检测出的异常通道留在较高精度；SmoothQuant 把一部分激活尺度迁移到权重；GPTQ 用近似曲率衡量不同权重误差对层输出的影响，AWQ 则用真实激活识别更重要的权重。它们分别处理异常通道、权重激活平衡和权重重要性，优化目标并不相同。</p><p>输入是待量化层与代表性校准激活，输出是范围、保留高精度通道或经过补偿的权重。盲目剪裁异常值可能伤害稀有 token、长上下文或特定语言，因为“异常”可能承载重要特征。校准集必须覆盖真实长度、领域和难例，不能只用短英文百科。</p><div class=\"dd-note warn\"><b>平均误差小不代表行为安全。</b>　少数关键 logits 排序翻转即可改变工具动作或拒答。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>PTQ、QAT 与量化基座训练<span class=\"dd-badge eng\">方法</span></h2><p class=\"dd-lead\">什么时候只用校准数据，什么时候需要重新训练？</p><p><b>PTQ</b>（训练后量化）在模型训练完成后估计尺度和补偿；<b>QAT</b>（量化感知训练）在训练前向中模拟舍入与截断，让权重适应误差；<b>QLoRA</b> 保持低位基座冻结，只训练高精度低秩适配器。三者的输出分别是量化模型、适应量化误差的新模型和可挂载适配器，不应混成同一产物。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方法</th><th>做法</th><th>成本</th><th>适合</th></tr></thead><tbody><tr><td>PTQ</td><td>训练后估尺度/补偿</td><td>低</td><td>权重 8/4 bit 起点</td></tr><tr><td>QAT</td><td>训练中模拟量化</td><td>高</td><td>低位宽/激活敏感</td></tr><tr><td>QLoRA</td><td>低位冻结基座+高精 LoRA</td><td>中</td><td>节省微调显存</td></tr></tbody></table></div><p>PTQ 不等于零数据：需要代表性校准或逐层优化。QAT 能适应误差但会引入训练数据与过拟合问题。QLoRA 训练时反量化基座参与计算，最终部署是否合并和重新量化要另做评测。应先从低成本 PTQ 基线开始，只有关键切片无法达标时再承担训练成本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>省显存不保证更快<span class=\"dd-badge eng\">硬件</span></h2><p class=\"dd-lead\">INT4 文件只有 FP16 四分之一，为什么端到端吞吐可能不升？</p><p>量化要在目标 GPU 或 CPU 上有匹配的打包格式、低位矩阵乘和融合内核；否则每步反量化、格式转换、kernel launch（启动一个计算内核的固定开销）或小 batch 会抵消带宽收益。权重下降也不等于 KV、激活和框架开销下降。</p><p>prefill 是一次处理整段输入提示，常更偏计算受限；decode 是逐 token 生成，常更偏权重读取带宽受限。输入是目标硬件、batch、提示与输出长度以及量化产物，输出应包括首 token 延迟、每 token 延迟、吞吐、峰值显存、功耗和加载时间。</p><p><b>SLO</b> 是服务承诺的延迟、可用性等目标。“能装进显存”只通过容量门，不等于延迟满足 SLO。CPU offload 把部分状态移到主机内存，虽能运行，PCIe 搬运仍可能让交互不可用。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>量化误差会与后续优化叠加<span class=\"dd-badge eng\">组合</span></h2><p class=\"dd-lead\">量化模型再做推测解码、LoRA 合并或 KV 压缩，能把单项测试相加吗？</p><p>不能。草稿/目标量化会改变接受率；LoRA 合并后权重范围变化，旧 scale 可能失效；KV 量化与长上下文注意力误差耦合；张量并行的量化布局影响通信。应按真实最终产物重新量化或校准，并端到端消融。</p><p>保留配方：基座哈希、权重/激活/KV 位宽、对称性、粒度、group size、校准集、算法、计算 dtype、内核和硬件。否则“同为 INT4”无法复现。</p><div class=\"dd-note warn\"><b>不可把压缩损失用更多重试隐藏。</b>　重试可能提高最终成功却增加成本、延迟和选择偏差。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测要抓排序翻转和长尾退化<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">平均困惑度只升 0.2%，为什么工具调用和安全仍可能明显变差？</p><p>输出由局部 logits 排序决定，小误差在接近决策边界时会翻转 token。按通用能力、目标任务、稀有 token、语言、长上下文、结构化输出、校准、拒答和对抗切片比较逐样本差异。</p><p>系统指标中，TTFT 是从请求到首 token 的时间，TPOT 是生成阶段平均每个后续 token 的时间；p50、p95、p99 是分别有 50%、95%、99% 请求不超过的延迟分位数。输入必须保持相同提示、采样、内核和负载，输出量化前后质量差、延迟区间、吞吐、显存、能耗与每成功任务成本。</p><p>平均困惑度小幅变化只表示整体 token 预测接近，不能排除少数关键动作排序翻转。保存逐样本失败并查看哪些切片退化，才能区分随机波动和系统性长尾损伤。</p><div class=\"dd-note\"><b>发布门槛：</b>只有硬风险切片不退化、系统收益在目标硬件成立，量化配置才是可行方案。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">量化是一套数值表示与硬件共同设计，不是把文件后缀改成 INT4。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>位宽越低一定越快</td><td>取决于内核、硬件、batch 和瓶颈</td></tr><tr><td>INT4 是完整配置</td><td>还需对象、粒度、算法、校准和计算 dtype</td></tr><tr><td>PTQ 不需要数据</td><td>通常需代表性校准/优化数据</td></tr><tr><td>平均误差小即可</td><td>关键 logits 排序和长尾行为可能翻转</td></tr><tr><td>权重缩四倍总显存也缩四倍</td><td>KV、激活、工作区和框架不同比缩放</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>线性代数、数值精度、神经网络与推理瓶颈</td></tr><tr><td><b>本页核心</b></td><td>scale/zero-point、粒度、异常值、PTQ/QAT、硬件内核</td></tr><tr><td>组合</td><td>LoRA/QLoRA、蒸馏、推理优化、KV cache</td></tr><tr><td>部署</td><td>模型选型、应用评测与可观测性</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>确定量化对象与目标硬件</li><li>用代表性数据选择范围/粒度</li><li>PTQ 或 QAT 生成候选</li><li>检查误差与关键 logits 翻转</li><li>目标负载测显存/延迟/吞吐</li><li>质量风险和每成功任务成本联合门禁</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>示例中 scale 为什么是 .4？</li><li>per-channel 为何通常误差更低？</li><li>PTQ 是否完全不需数据？</li><li>INT4 为何可能不快？</li><li>为什么要测逐样本排序翻转？</li><li>假设“量化：把连续参数压到有限格点”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>对称 INT3 正上限为 3，最大绝对值 1.2，所以 s=1.2/3。</li><li>每通道可用独立范围，不被其他通道异常值支配。</li><li>通常仍需代表性校准或逐层优化数据。</li><li>缺低位内核、反量化/转换开销或当前瓶颈不在权重带宽。</li><li>小数值误差可能改变关键 token、工具动作或安全决策。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2208.07339\" target=\"_blank\" rel=\"noopener\">LLM.int8()</a>：大模型异常值与混合精度</li><li><a href=\"https://arxiv.org/abs/2210.17323\" target=\"_blank\" rel=\"noopener\">GPTQ</a>：二阶近似训练后权重量化</li><li><a href=\"https://arxiv.org/abs/2211.10438\" target=\"_blank\" rel=\"noopener\">SmoothQuant</a>：权重—激活尺度迁移</li><li><a href=\"https://arxiv.org/abs/2306.00978\" target=\"_blank\" rel=\"noopener\">AWQ</a>：激活感知权重量化</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
